import React, { useEffect, useRef, useState, useCallback } from "react";
import Chart from "chart.js/auto";

const SMOGON_PATH = "/smogon_csv/";
const POKE_PATH = "/pokemon_data/";

// Normalize names for matching
const normalize = (name) =>
  name.toLowerCase().replace(/[^a-z0-9]/g, "");

export default function ComUsage() {
  const chartRef = useRef(null);
  const canvasRef = useRef(null);

  const [files, setFiles] = useState([]);
  const [pokemonList, setPokemonList] = useState([]);
  const [filteredList, setFilteredList] = useState([]);
  const [search, setSearch] = useState("");

  const [selectedPokemon, setSelectedPokemon] = useState("");
  const [compareList, setCompareList] = useState([]);
  const [selectedGen, setSelectedGen] = useState("9");
  const [menuOpen, setMenuOpen] = useState(false);

  // Load Smogon file list
  useEffect(() => {
    fetch(SMOGON_PATH + "files.json")
      .then(res => res.json())
      .then(data => setFiles(data.files));
  }, []);

  // Safe CSV loader
  const loadCSV = async (path) => {
    const res = await fetch(path);
    return await res.text();
  };

  // FIXED CSV parser (handles spaces + \r)
  const parseCSV = (text) =>
    text
      .trim()
      .split("\n")
      .slice(1)
      .map(r => r.split(",").map(c => c.trim()));

  // Load Pokémon list
  useEffect(() => {
    const loadPokemonData = async () => {
      const text = await loadCSV(POKE_PATH + "pokemon_all.csv");
      const rows = parseCSV(text);

      const list = rows
        .map(row => row[1])
        .filter(name => name)
        .sort();

      setPokemonList(list);
      setFilteredList(list);
    };

    loadPokemonData();
  }, []);

  // Default selection
  useEffect(() => {
    if (!selectedPokemon && pokemonList.length > 0) {
      setSelectedPokemon(pokemonList[0]);
    }
  }, [pokemonList, selectedPokemon]);

  // FIXED search (normalized)
  useEffect(() => {
    const filtered = pokemonList.filter(p =>
      normalize(p).includes(normalize(search))
    );
    setFilteredList(filtered);
  }, [search, pokemonList]);

  const addToCompare = () => {
    if (selectedPokemon && !compareList.includes(selectedPokemon)) {
      setCompareList([...compareList, selectedPokemon]);
    }
  };

  const removeFromCompare = (name) => {
    setCompareList(compareList.filter(p => p !== name));
  };

  // FIXED data extraction
  const getUsageData = useCallback(async () => {
    const sortedFiles = [...files]
      .filter(f => f.includes(`gen${selectedGen}`))
      .sort();

    const labels = sortedFiles.map(f => f.split("_")[0]);

    const datasets = [];

    for (let pokemon of compareList) {
      const data = [];

      for (let file of sortedFiles) {
        const text = await loadCSV(SMOGON_PATH + file);
        const rows = parseCSV(text);

        const match = rows.find(
          r => normalize(r[1]) === normalize(pokemon)
        );

        if (match && match[2]) {
          data.push(parseFloat(match[2]));
        } else {
          data.push(0);
        }
      }

      datasets.push({
        label: pokemon,
        data,
        tension: 0.3,
        borderWidth: 2,
        pointRadius: 3,
        borderColor: `hsl(${Math.random() * 360},70%,50%)`,
        spanGaps: true
      });
    }

    return { labels, datasets };
  }, [files, selectedGen, compareList]);

  // Build chart
  useEffect(() => {
    if (compareList.length === 0) {
      if (chartRef.current) {
        chartRef.current.destroy();
        chartRef.current = null;
      }
      return;
    }

    const buildChart = async () => {
      const { labels, datasets } = await getUsageData();

      if (chartRef.current) chartRef.current.destroy();

      chartRef.current = new Chart(canvasRef.current, {
        type: "line",
        data: { labels, datasets },
        options: {
          responsive: true,
          plugins: {
            legend: { position: "top" }
          },
          scales: {
            x: {
              title: {
                display: true,
                text: "Date"
              }
            },
            y: {
              title: {
                display: true,
                text: "Usage (%)"
              },
              beginAtZero: true
            }
          }
        }
      });
    };

    buildChart();
  }, [getUsageData, compareList]);

  return (
    <div>
      <h2>Pokémon Usage Over Time</h2>

      <div style={{ position: "absolute", top: 20, right: 20 }}>
        <button onClick={() => setMenuOpen(!menuOpen)}>☰</button>
      </div>

      {menuOpen && (
        <div style={{
          position: "absolute",
          top: 60,
          right: 20,
          background: "#eee",
          padding: "15px",
          borderRadius: "8px",
          width: "250px",
          maxHeight: "500px",
          overflowY: "auto"
        }}>
          <h4>Filters</h4>

          <label>Generation:</label>
          <select
            value={selectedGen}
            onChange={(e) => setSelectedGen(e.target.value)}
          >
            {[6,7,8,9].map(g => (
              <option key={g} value={g}>Gen {g}</option>
            ))}
          </select>

          <br /><br />

          <label>Search Pokémon:</label>
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            style={{ width: "100%" }}
          />

          <br /><br />

          <select
            size="5"
            style={{ width: "100%" }}
            value={selectedPokemon}
            onChange={(e) => setSelectedPokemon(e.target.value)}
          >
            {filteredList.map(p => (
              <option key={p}>{p}</option>
            ))}
          </select>

          <br /><br />

          <button onClick={addToCompare} style={{ width: "100%" }}>
            Add to Compare
          </button>

          <hr />

          <h4>Compare List</h4>
          {compareList.map(p => (
            <div key={p} style={{
              display: "flex",
              justifyContent: "space-between"
            }}>
              <span>{p}</span>
              <button onClick={() => removeFromCompare(p)}>X</button>
            </div>
          ))}
        </div>
      )}

      <canvas ref={canvasRef}></canvas>
    </div>
  );
}
